# Óleo e filtros por veículo (14/11/2026), etapa 1: tela de pesquisa por modelo (#/oleo-filtros), só leitura.
# Confere: busca pela placa (cadastro sem custo; fora do cadastro pela consulta, sem cadastrar), tela resumida (óleo em uma linha por resposta, uma aplicação de filtros, detalhes e outras versões atrás de botões),
# botão da barra de cima do PC e "Mais" do celular, pesquisa por modelo e ano, litros e viscosidade, filtros com Tecfil/Mahle/MANN,
# prioridade do estoque (aparece só o do estoque + Conversão), saldo zerado, quadro de conversão, sem rolagem lateral no celular,
# menu lateral e barra de cima do PC cabendo em 1366x768 e que a tela não grava nada.
# Uso: python3 teste/teste_oleo_filtros.py [pasta das fotos]   (precisa de: pip install playwright && playwright install chromium)
import subprocess, time, sys, os, tempfile
from playwright.sync_api import sync_playwright
RAIZ = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
srv = subprocess.Popen([sys.executable, "-m", "http.server", "8771", "-d", RAIZ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
time.sleep(1); ok = []; falhas = []; erros = []
def chk(n, c, extra=""): (ok if c else falhas).append(n if c or not extra else n + " :: " + str(extra))
U = "http://localhost:8771/"; TMP = sys.argv[1] if len(sys.argv) > 1 else tempfile.mkdtemp()
# estoque de mentira: MANN do filtro de óleo da Hilux 204 cv (equivale ao Tecfil PSL916) com saldo; Wega do mesmo filtro zerado
PREP = """(() => { const db = window.__DB; const p = (id, referencia, marca, estoque_atual, categoria) => db.produtos.push({ id, codigo: 900 + db.produtos.length, tipo: 'produto', ativo: true, unidade: 'UN', controla_estoque: true,
    descricao: 'FILTRO ' + referencia, referencia, marca, estoque_atual, categoria, preco_vista: 50 });
  p('f1', 'W 7283 MANN', 'MANN', 3, 'FILTROS LUB'); p('f2', 'W7283 S/NF', 'MANN', 2, 'FILTROS LUB'); p('f3', 'JFA0288', 'WEGA', 0, 'FILTRO AR MOTOR'); p('f4', 'FAC889 S/NF', 'VOX', 4, 'FILTROS'); })();"""
def abrir(b, w, h):
  pg = b.new_context(viewport={"width": w, "height": h}).new_page()
  pg.on("pageerror", lambda e: erros.append(str(e)))
  pg.add_init_script(path=os.path.join(RAIZ, "teste", "mock.js"))
  pg.add_init_script(PREP)  # o estoque entra antes de o sistema carregar os produtos
  pg.goto(U + "#/painel"); pg.wait_for_timeout(1500)
  return pg
def buscar(pg, q, ano=""):
  pg.fill("#of-q", q); pg.fill("#of-ano", ano); pg.wait_for_timeout(500)
try:
  with sync_playwright() as p:
    b = p.chromium.launch()
    # ---------- PC ----------
    pg = abrir(b, 1366, 768)
    chk("PC: botão 'Óleo e filtros' na barra de cima", pg.locator(".barra-topo button.bt-oleo").count() == 1 and pg.locator(".barra-topo button.bt-oleo").is_visible())
    rol = pg.evaluate("() => { const l = document.querySelector('.lateral'); return [l.scrollHeight, l.clientHeight]; }")
    chk("PC: menu lateral cabe em 1366x768 sem barra de rolagem", rol[0] <= rol[1], rol)
    cab = pg.evaluate("() => { const b = document.querySelector('.barra-topo'); return [b.scrollWidth, b.clientWidth]; }")
    chk("PC: a barra de cima continua cabendo em 1366", cab[0] <= cab[1], cab)
    pg.locator(".barra-topo button.bt-oleo").click(); pg.wait_for_timeout(1500)
    chk("PC: abre a tela", pg.locator("#of-q").count() == 1 and "#/oleo-filtros" in pg.url)
    chk("PC: título da tela na barra de cima", pg.locator(".bt-titulo").inner_text() == "Óleo e filtros")
    chk("sem busca: pede o modelo, sem resultado", pg.locator("#of-oleo").count() == 0 and pg.locator(".vazio", has_text="Digite o modelo").count() == 1)
    buscar(pg, "hilux 2.8", "2023")
    ol = pg.locator("#of-oleo .of-oleo")
    chk("Hilux 2.8 2023: óleo resumido numa linha só (8 L, 5W30)", ol.count() == 1 and ol.first.locator(".of-litros").inner_text() == "8 L" and ol.first.locator(".of-visc").inner_text() == "5W30", ol.all_inner_texts())
    chk("Hilux 204 cv: avisa que não foi conferido", ol.first.locator(".of-selo-aviso", has_text="Não conferido").count() == 1)
    chk("resumo do óleo: sem norma e sem fonte na tela", "Fonte:" not in pg.locator("#of-oleo").inner_text() and "Norma:" not in pg.locator("#of-oleo").inner_text())
    chk("resumo do óleo: linha de tabela com erro conhecido (5,9 L) não aparece", "5,9" not in pg.locator("#of-oleo").inner_text())
    pg.locator("#of-det-oleo").click(); pg.wait_for_timeout(200)
    det = pg.locator("#of-oleo .of-oleo-det")
    chk("detalhes do óleo: todas as linhas, com fonte, norma e o aviso do 5,9 L", det.count() >= 4 and pg.locator("#of-oleo .of-oleo-pe", has_text="Fonte:").count() == det.count() and "Norma:" in pg.locator("#of-oleo").inner_text() and pg.locator("#of-oleo .of-selo-aviso", has_text="Não use 5,9 L").count() >= 1, det.count())
    pg.locator("#of-det-oleo").click(); pg.wait_for_timeout(200)
    chk("detalhes do óleo: volta ao resumo", pg.locator("#of-oleo .of-oleo-det").count() == 0 and pg.locator("#of-oleo .of-oleo").count() == 1)
    chk("filtros: uma aplicação só no resumo (mais o que só outro catálogo liga ao estoque)", pg.locator("#of-filtros .of-app").count() == 2, pg.locator("#of-filtros .of-app").count())
    a = pg.locator("#of-filtros .of-app").first
    chk("filtros: a aplicação mostrada é a 204 cv de 2022 em diante", "204cv" in a.locator("header").inner_text() and "2022 em diante" in a.locator("header").inner_text(), a.locator("header").inner_text())
    chk("filtros: os quatro filtros, um por linha", a.locator(".of-filtro").count() == 4 and [x.inner_text() for x in a.locator(".of-tipo").all()] == ["Óleo", "Ar", "Combustível", "Cabine"])
    lo = a.locator(".of-filtro").nth(0)
    chk("filtro de óleo no estoque: aparece só o do estoque, com a quantidade somada", lo.locator(".of-est-item").count() == 1 and "MANN W7283" in lo.inner_text() and "(5 un.)" in lo.inner_text() and "Em estoque" in lo.inner_text(), lo.inner_text())
    chk("filtro de óleo no estoque: não lista Tecfil/Mahle/MANN ao lado", lo.locator(".of-marca").count() == 0 and "PSL916" not in lo.inner_text())
    chk("filtro de óleo no estoque: tem o botão Conversão", lo.locator("button", has_text="Conversão").count() == 1)
    la = a.locator(".of-filtro").nth(1)
    chk("filtro de ar fora do estoque: Tecfil, Mahle e MANN (traço onde não há código)", la.locator(".of-marca").count() == 3 and "ARL2219" in la.inner_text() and la.locator(".of-traco").count() == 2, la.inner_text())
    chk("filtro de ar: cadastrado sem saldo fica avisado e não vira estoque", "Cadastrado, sem saldo" in la.inner_text() and "JFA0288" in la.inner_text() and la.locator(".of-est-item").count() == 0)
    chk("resumo dos filtros: sem observação do catálogo", "Óleo 2:" not in a.inner_text() and a.locator("footer").count() == 0)
    chk("outras marcas não aparecem fora da conversão", all(m not in a.inner_text() for m in ["JFO0215", "LB916", "PH3614", "90915YZZD4"]), a.inner_text())
    # filtro que só o catálogo de outra marca liga ao carro (cabine Vox FAC889): aparece em "Também no seu estoque", só a linha dele
    e2 = pg.locator("#of-filtros h4:has-text('Também no seu estoque') ~ .of-app").first
    chk("estoque achado por outro catálogo: só a linha do filtro, com o catálogo escrito", e2.locator(".of-filtro").count() == 1 and "Vox FAC889" in e2.inner_text() and "(4 un.)" in e2.inner_text() and "Catálogo Vox" in e2.inner_text(), e2.inner_text())
    lo.locator("button", has_text="Conversão").click(); pg.wait_for_timeout(300)
    md = pg.locator(".modal")
    chk("conversão: abre com o estoque, as outras marcas e o original", md.count() == 1 and "Em estoque: MANN W7283 (5 un.)" in md.inner_text() and all(x in md.inner_text() for x in ["Tecfil", "PSL916", "Wega", "JFO0215", "Vox", "LB916", "Toyota", "90915YZZD4"]), md.inner_text())
    pg.screenshot(path=os.path.join(TMP, "pc_conversao.png"))
    md.locator("button", has_text="Fechar").last.click(); pg.wait_for_timeout(200)
    chk("conversão: fecha", pg.locator(".modal").count() == 0)
    alt = pg.evaluate("() => document.documentElement.scrollHeight")
    chk("PC: o resumo da Hilux fica em até 1200 px de altura (antes: 3160)", alt <= 1200, alt)
    pg.screenshot(path=os.path.join(TMP, "pc_hilux.png"), full_page=True)
    vs = pg.locator("#of-versoes")
    chk("outras versões ficam atrás de um botão", vs.count() == 1 and vs.get_attribute("aria-expanded") == "false" and "(3)" in vs.inner_text(), vs.inner_text())
    vs.click(); pg.wait_for_timeout(300)
    chk("outras versões: abre as demais aplicações da Tecfil, com o catálogo e a observação", pg.locator("#of-filtros .of-app").count() == 5 and pg.locator("#of-filtros footer", has_text="Catálogo Tecfil 2026").count() == 4, pg.locator("#of-filtros .of-app").count())
    outros = pg.locator("button.of-outros")
    chk("outros catálogos: segundo botão, recolhido", outros.count() == 1 and outros.get_attribute("aria-expanded") == "false")
    n1 = pg.locator("#of-filtros .of-app").count(); outros.click(); pg.wait_for_timeout(300)
    chk("outros catálogos: abre ao clicar", pg.locator("#of-filtros .of-app").count() > n1 and pg.locator("#of-filtros footer", has_text="Catálogo MANN").count() >= 1)
    buscar(pg, "gm onix 1,0", "2015")
    chk("Onix 1.0 2015: 3,5 L e 5W30 na primeira linha", pg.locator("#of-oleo .of-oleo").first.locator(".of-litros").inner_text() == "3,5 L" and pg.locator("#of-oleo .of-oleo").first.locator(".of-visc").inner_text() == "5W30", pg.locator("#of-oleo .of-oleo").first.inner_text())
    chk("Onix: no máximo três linhas de óleo no resumo", pg.locator("#of-oleo .of-oleo").count() <= 3)
    chk("Onix: nova busca volta ao resumo (versões recolhidas)", pg.locator("#of-filtros .of-app").count() == 1 and pg.locator("button.of-outros").count() == 0)
    chk("Onix: filtros sem estoque mostram as três marcas", pg.locator("#of-filtros .of-app").first.locator(".of-filtro").nth(0).locator(".of-marca").count() == 3)
    chk("Onix 2015: sem sinal de atenção (as fontes concordam no 5W30)", pg.locator("#of-atencao").count() == 0)
    buscar(pg, "onix 1.0", "2021")
    chk("Onix 1.0 2021: sinal de atenção escrito, com o 5W30 do turbo e o 0W20 do aspirado", pg.locator("#of-atencao").count() == 1 and "Atenção" in pg.locator("#of-atencao").inner_text() and "5W30" in pg.locator("#of-atencao").inner_text() and "0W20" in pg.locator("#of-atencao").inner_text(), pg.locator("#of-atencao").inner_text() if pg.locator("#of-atencao").count() else "")
    pg.screenshot(path=os.path.join(TMP, "pc_onix_2021.png"), full_page=True)
    pg.screenshot(path=os.path.join(TMP, "pc_onix.png"), full_page=True)
    # ---------- busca pela placa ----------
    cham = lambda: pg.evaluate("((window.__PLACA || {}).chamadas || []).filter(c => c.acao !== 'saldo')")
    buscar(pg, "QXN1E49"); pg.wait_for_timeout(1200)   # Toyota Hilux 2022 do cadastro
    fx = pg.locator("#of-placa")
    chk("placa do cadastro: usa o cadastro e não chama a consulta paga", fx.count() == 1 and "do cadastro: Toyota Hilux 2022" in fx.inner_text() and len(cham()) == 0, [fx.inner_text() if fx.count() else "", cham()])
    chk("placa do cadastro: mostra por quais palavras buscou", "Buscando por: HILUX 2022" in fx.inner_text(), fx.inner_text())
    chk("placa do cadastro: traz óleo e filtros da Hilux", pg.locator("#of-oleo .of-oleo").count() >= 1 and "Hilux" in pg.locator("#of-filtros .of-app header").first.inner_text())
    buscar(pg, "qxn-1e49"); pg.wait_for_timeout(600)
    chk("placa com traço e minúscula também vale", pg.locator("#of-placa").count() == 1 and len(cham()) == 0)
    pg.screenshot(path=os.path.join(TMP, "pc_placa.png"), full_page=True)
    buscar(pg, "INT8C36"); pg.wait_for_timeout(1800)   # fora do cadastro: a consulta de mentira responde um VW CrossFox
    fx = pg.locator("#of-placa"); c = cham()
    chk("placa fora do cadastro: uma consulta básica só", len(c) == 1 and c[0]["acao"] == "basico" and c[0]["placa"] == "INT8C36", c)
    chk("placa fora do cadastro: diz de onde veio e o que entendeu", "fora do cadastro, pela consulta da placa" in fx.inner_text() and "Buscando por: CROSSFOX" in fx.inner_text(), fx.inner_text())
    chk("placa fora do cadastro: traz os filtros do CrossFox", pg.locator("#of-filtros .of-app").count() >= 1 and "CrossFox" in pg.locator("#of-filtros .of-app header").first.inner_text(), pg.locator("#of-filtros .of-app header").first.inner_text() if pg.locator("#of-filtros .of-app").count() else "")
    chk("placa fora do cadastro: a tela não cadastra o veículo", pg.evaluate("() => window.__DB.veiculos.some(v => v.placa === 'INT8C36')") is False)
    buscar(pg, "hilux"); buscar(pg, "INT8C36"); pg.wait_for_timeout(1500)
    chk("a mesma placa não é consultada duas vezes", len(cham()) == 1, cham())
    buscar(pg, "ZZZ9Z99"); pg.wait_for_timeout(1800)
    chk("placa que a consulta não acha: avisa e pede o modelo", "placa não encontrada" in pg.locator("#of-placa").inner_text() and pg.locator("#of-filtros").count() == 0)
    pg.evaluate("() => { window.__PLACA.situacao = 'saldo'; }"); buscar(pg, "ABD2E34"); pg.wait_for_timeout(1800)
    chk("consulta sem saldo: avisa e pede o modelo, sem travar", "sem saldo" in pg.locator("#of-placa").inner_text() and pg.locator(".vazio", has_text="Carregando").count() == 0, pg.locator("#of-placa").inner_text())
    pg.evaluate("() => { window.__PLACA.situacao = ''; }")
    buscar(pg, "gol 1.6", "2012")
    chk("modelo digitado continua sem faixa de placa", pg.locator("#of-placa").count() == 0)
    buscar(pg, "xyzxyz")
    chk("modelo que não existe: mensagem clara", pg.locator(".vazio", has_text="Nada no catálogo").count() == 1)
    buscar(pg, "gol 1.6", "2012"); pg.goto(U + "#/painel"); pg.wait_for_timeout(600); pg.goto(U + "#/oleo-filtros"); pg.wait_for_timeout(1200)
    chk("a última busca fica guardada no aparelho", pg.input_value("#of-q") == "gol 1.6" and pg.input_value("#of-ano") == "2012" and pg.locator("#of-filtros .of-app").count() >= 1)
    chk("só leitura: estoque do cadastro não mudou", pg.evaluate("() => window.__DB.produtos.find(x => x.id === 'f1').estoque_atual") == 3)
    # ---------- celular ----------
    cel = abrir(b, 390, 844)
    cel.goto(U + "#/mais"); cel.wait_for_timeout(800)
    chk("celular: 'Mais' tem Óleo e filtros", cel.locator(".linha", has_text="Óleo e filtros").count() == 1)
    cel.locator(".linha", has_text="Óleo e filtros").click(); cel.wait_for_timeout(1500)
    buscar(cel, "hilux 2.8", "2023")
    chk("celular: resultado aparece", cel.locator("#of-oleo .of-oleo").count() >= 1 and cel.locator("#of-filtros .of-app").count() >= 1)
    larg = cel.evaluate("() => [document.documentElement.scrollWidth, window.innerWidth]")
    chk("celular: sem rolagem lateral", larg[0] <= larg[1], larg)
    chk("celular: estoque primeiro também", "MANN W7283" in cel.locator("#of-filtros .of-app").first.locator(".of-filtro").nth(0).inner_text())
    alt = cel.evaluate("() => document.documentElement.scrollHeight")
    chk("celular: o resumo da Hilux fica em até duas telas (1700 px)", alt <= 1700, alt)
    cel.screenshot(path=os.path.join(TMP, "cel_hilux.png"), full_page=True)
    cel.locator("#of-filtros .of-app").first.locator("button", has_text="Conversão").first.click(); cel.wait_for_timeout(300)
    larg = cel.evaluate("() => [document.documentElement.scrollWidth, window.innerWidth]")
    chk("celular: conversão abre sem rolagem lateral", cel.locator(".modal").count() == 1 and larg[0] <= larg[1], larg)
    cel.screenshot(path=os.path.join(TMP, "cel_conversao.png"))
    chk("nenhum erro de script", not erros, erros[:3])
finally:
  srv.terminate()
print(len(ok), "verificações passaram" + ("; " + str(len(falhas)) + " FALHARAM:" if falhas else "."))
for f in falhas: print("  ✗", f)
print("fotos em", TMP); sys.exit(1 if falhas else 0)
